scripts.build:
vite build && esbuild server/_core/index.ts --platform=node --packages=external --bundle --format=esm --outdir=dist && mkdir -p api && rm -f api/index.js api/storage.js api/index.js.map api/storage.js.map && esbuild server/_core/vercel-api.ts --platform=node --bundle --format=cjs --outfile=api/index.js && printf '
module.exports = module.exports.default;
' >> api/index.js && esbuild server/_core/vercel-storage.ts --platform=node --bundle --format=cjs --outfile=api/storage.js && printf '
module.exports = module.exports.default;
' >> api/storage.js
